 private final int INK=Color.rgb(25,43,55),TEAL=Color.rgb(13,115,108),MUTED=Color.rgb(86,104,116),BG=Color.rgb(245,247,249),LINE=Color.rgb(221,229,234),WARN=Color.rgb(147,68,24);
 private Store db;private LinearLayout root,body;private TextView saveState;private String currentId=null,screen="home";private Map<String,String> answers;private int step=0;private boolean dirty=false,completed=false;private SharedPreferences prefs;
